    const sm = S.attMonth, ms = monthStats(sm.y, sm.m), pm = S.patMonth, ps = monthStats(pm.y, pm.m), te = S.trendEnd;
    const tr = Array.from({ length: 6 }, (_, i) => ym(te.y, te.m - 5 + i)), trv = tr.map(x => futureYM(x.y, x.m) ? 0 : monthStats(x.y, x.m).pct);
    const cm = S.calMonth, first = new Date(cm.y, cm.m, 1), lead = (first.getDay() + 6) % 7, days = new Date(cm.y, cm.m + 1, 0).getDate();
